    function parseCSV(text) {
      const lines = text.trim().split(/\r?\n/);
      if (lines.length < 2) return [];
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
      
      const records = [];
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',').map(p => p.trim());
        const row = {};
        headers.forEach((h, idx) => {
          row[h] = parts[idx];
        });

        const registered = parseInt(row['pregnancies_registered'], 10) || 0;
        const completed = parseInt(row['anc4_completed'], 10) || 0;
        const rate = registered > 0 ? (completed / registered) * 100 : 0;

        records.push({
          district: row['district'] || 'Unknown',
          year: parseInt(row['year'], 10) || 0,
          pregnancies_registered: registered,
          anc4_completed: completed,
          source: row['source'] || 'N/A',
          rate: rate,
          rateFormatted: rate.toFixed(2)
        });
      }
      return records;
    }

    // Load data from anc4_coverage.csv or fallback
    async function loadData() {
      try {
        const res = await fetch('anc4_coverage.csv');
